package io.forgeloop.support.application;
import io.forgeloop.support.domain.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.util.*; import org.junit.jupiter.api.*;
class TicketAssignmentServiceTest {
 Organization acme=new Organization("acme","Acme"), other=new Organization("other","Other"); Member admin=new Member("admin","Admin",Role.ADMIN,acme), member=new Member("member","Member",Role.MEMBER,acme), outsider=new Member("out","Out",Role.MEMBER,other); Ticket ticket=new Ticket("t1","Issue",acme); TicketRepository tickets=mock(TicketRepository.class); MemberRepository members=mock(MemberRepository.class); AuditEventRepository audits=mock(AuditEventRepository.class); TicketAssignmentService service=new TicketAssignmentService(tickets,members,audits);
 @Test void assignsAndAuditsWithinOrganization(){when(tickets.findById("t1")).thenReturn(Optional.of(ticket));when(members.findById("admin")).thenReturn(Optional.of(admin));when(members.findById("member")).thenReturn(Optional.of(member));when(tickets.save(ticket)).thenReturn(ticket); Ticket result=service.assign("admin","t1","member"); assertEquals("member",result.getAssignee().getId());verify(audits).save(any(AuditEvent.class));}
 @Test void rejectsCrossOrganizationAssignee(){when(tickets.findById("t1")).thenReturn(Optional.of(ticket));when(members.findById("admin")).thenReturn(Optional.of(admin));when(members.findById("out")).thenReturn(Optional.of(outsider));assertThrows(AssignmentForbiddenException.class,()->service.assign("admin","t1","out"));verifyNoInteractions(audits);}
 @Test void rejectsNonAdmin(){when(tickets.findById("t1")).thenReturn(Optional.of(ticket));when(members.findById("member")).thenReturn(Optional.of(member));when(members.findById("out")).thenReturn(Optional.of(outsider));assertThrows(AssignmentForbiddenException.class,()->service.assign("member","t1","out"));}
}
